async function fetchAvatar(path){const encoded=String(path).split('/').map(encodeURIComponent).join('/'),res=await fetch(`${SB_URL}/storage/v1/object/authenticated/avatars/${encoded}?v=${Date.now()}`,{headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`},cache:'no-store'});if(!res.ok)throw Error(`avatar ${res.status}`);const next=URL.createObjectURL(await res.blob());if(avatarUrl)try{URL.revokeObjectURL(avatarUrl)}catch{}avatarUrl=next;return next}
